public class DiffieHellman{public static void main(String[]x){int p=23,g=5,a=4,b=3,A=(int)(Math.pow(g,a)%p),B=(int)(Math.pow(g,b)%p),as=(int)(Math.pow(B,a)%p),bs=(int)(Math.pow(A,b)%p);System.out.println("Alice Sends: "+A);System.out.println("Bob Computes: "+bs);System.out.println("Bob Sends: "+B);System.out.println("Alice Computes: "+as);System.out.println("Shared Secret: "+as);System.out.println(as==bs?"Success: Shared Secrets Matches!":"Error: Shared Secrets does not Match");}}
